draw:
function arrow(x1,y1,x2,y2,col,wid){
  ctx.strokeStyle=col; ctx.fillStyle=col; ctx.lineWidth=wid;
  ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
  var a=Math.atan2(y2-y1,x2-x1), s=7;
  ctx.beginPath();
  ctx.moveTo(x2,y2);
  ctx.lineTo(x2-s*Math.cos(a-0.4), y2-s*Math.sin(a-0.4));
  ctx.lineTo(x2-s*Math.cos(a+0.4), y2-s*Math.sin(a+0.4));
  ctx.closePath(); ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var th = p.theta * Math.PI / 180;
var cx = W * 0.22, cy = H * 0.72;
var L = Math.min(W, H) * 0.34;
var R = Math.min(W * 0.62, H * 0.72);

// the wire the element sits in
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(cx - L * 0.8, cy); ctx.lineTo(cx + L * 1.9, cy); ctx.stroke();

// the current element
arrow(cx, cy, cx + L, cy, C.accent, 3);
ctx.fillStyle = C.accent;
ctx.fillText("I dl  (current element)", cx + 4, cy + 18);

// r-hat from the element to the field point
var px = cx + R * Math.cos(th), py = cy - R * Math.sin(th);
arrow(cx, cy, px, py, C.figure, 1.5);
ctx.fillStyle = C.figure;
ctx.fillText("r", cx + R * 0.52 * Math.cos(th) - 10, cy - R * 0.52 * Math.sin(th) - 6);

// the angle
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(cx, cy, 34, -th, 0); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("angle " + p.theta.toFixed(0) + " deg", cx + 40, cy - 14 - 22 * Math.sin(th));

// field point
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px, py, 3.5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("P", px + 8, py - 6);

// dB at P: out of the page, size proportional to sin(theta)
var s = Math.abs(Math.sin(th));
var rad = 5 + 16 * s;
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(px, py, rad, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(px, py, 2.5 + 2 * s, 0, Math.PI * 2); ctx.fill();
ctx.fillText("dB out of the page", px - 30, py + rad + 16);

// a reminder bar of how big that is
var bx = W * 0.06, by = H * 0.16, bw = W * 0.34;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.strokeRect(bx, by, bw, 10);
ctx.fillStyle = C.accent;
ctx.fillRect(bx, by, bw * s, 10);
ctx.fillStyle = C.ink;
ctx.fillText("dB as a fraction of its largest value", bx, by - 6);

out.note = "sin of the angle = " + s.toFixed(3) + "  -  an element sends nothing straight ahead of itself (0 or 180 deg) and the most out sideways (90 deg)";
